/**
 * Generate the ABI metadata and typed wrappers from qubic/core.
 *
 * Usage:
 *   bun scripts/generate.ts                 # fetch qubic/core main and write src/generated
 *   bun scripts/generate.ts --check         # exit 1 if generated files are stale
 *   QUBIC_CORE_DIR=../core bun scripts/generate.ts
 *   bun scripts/generate.ts --ref <sha>
 *
 * The output is deterministic for a given core commit. `abi-hash.ts` covers
 * only the ABI itself (not provenance), so the weekly sync workflow can decide
 * whether a release is needed without publishing for source-only changes.
 */

import { createHash } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import type {
	ContractDefinition,
	ContractMetadata,
	StructScope,
} from '../src/types.js'
import { buildContracts } from './lib/build-abi.js'
import {
	emitContracts,
	emitGeneratedIndex,
	emitMetadata,
	emitQpi,
	emitTypes,
	summarize,
} from './lib/emit.js'
import { fetchCoreSource } from './lib/fetch-core.js'

interface Args {
	check: boolean
	ref?: string
	source?: string
	out: string
	quiet: boolean
}

function parseArgs(argv: string[]): Args {
	const args: Args = { check: false, out: 'src/generated', quiet: false }
	for (let index = 0; index < argv.length; index++) {
		const arg = argv[index]
		switch (arg) {
			case '--check':
				args.check = true
				break
			case '--quiet':
				args.quiet = true
				break
			case '--ref':
				args.ref = argv[++index]
				break
			case '--source':
				args.source = argv[++index]
				break
			case '--out':
				args.out = argv[++index] ?? args.out
				break
			case '--help':
			case '-h':
				printHelp()
				process.exit(0)
				break
			default:
				throw new Error(`Unknown argument: ${arg}`)
		}
	}
	return args
}

function printHelp(): void {
	console.log(`Generate @glyph-oss/contracts from qubic/core.

Options:
  --check           verify generated files are up to date without writing
  --ref <ref>       qubic/core branch, tag, or commit (default: main)
  --source <dir>    local qubic/core checkout (or set QUBIC_CORE_DIR)
  --out <dir>       output directory (default: src/generated)
  --quiet           only print warnings/errors
`)
}

function abiHash(contracts: ContractDefinition[], qpi: StructScope): string {
	return createHash('sha256')
		.update(JSON.stringify({ contracts, qpi }))
		.digest('hex')
}

async function main(): Promise<void> {
	const args = parseArgs(process.argv.slice(2))
	const outDir = resolve(args.out)
	const localSource = args.source ?? process.env.QUBIC_CORE_DIR
	const source = await fetchCoreSource({
		...(args.ref === undefined ? {} : { ref: args.ref }),
		...(localSource === undefined ? {} : { dir: localSource }),
		log: args.quiet ? undefined : (message) => console.log(message),
	})

	const { contracts, qpi, warnings } = buildContracts(source)
	for (const warning of warnings) console.warn(`warning: ${warning}`)

	const metadata: ContractMetadata = {
		schemaVersion: 1,
		source: source.source,
		qpi,
		contracts,
	}
	const hash = abiHash(contracts, qpi)

	const files = new Map<string, string>([
		['metadata.ts', emitMetadata(metadata)],
		['types.ts', emitTypes(contracts, source.source.commit)],
		['contracts.ts', emitContracts(contracts, source.source.commit)],
		['qpi.ts', emitQpi(source.source.commit)],
		['index.ts', emitGeneratedIndex(source.source.commit)],
		[
			'abi-hash.ts',
			`// @generated by scripts/generate.ts from qubic/core ${source.source.commit}. Do not edit by hand.\n\nexport const ABI_HASH = "${hash}"\n`,
		],
	])

	if (args.check) {
		const stale: string[] = []
		for (const [name, content] of files) {
			const path = join(outDir, name)
			const existing = await readFile(path, 'utf8').catch(() => undefined)
			if (existing !== content) stale.push(path)
		}
		if (stale.length > 0) {
			console.error(`Generated ABI is stale (${stale.length} file(s)):`)
			for (const path of stale) console.error(`  ${path}`)
			console.error('Run `bun run generate` and commit the result.')
			process.exit(1)
		}
		if (!args.quiet) console.log('Generated ABI is up to date.')
		return
	}

	await mkdir(outDir, { recursive: true })
	for (const [name, content] of files) {
		await writeFile(join(outDir, name), content)
	}

	if (!args.quiet) {
		const summary = summarize(contracts)
		console.log(
			`generated ${summary.contractCount} contracts, ${summary.procedureCount} procedures, ` +
				`${summary.functionCount} functions, ${summary.notificationCount} notifications`,
		)
		console.log(
			`source: qubic/core ${source.source.commit.slice(0, 12)} (${source.source.commitDate})`,
		)
		console.log(`abi: ${hash}`)
		console.log(`wrote ${files.size} files to ${outDir}`)
	}
}

main().catch((error: unknown) => {
	console.error(
		error instanceof Error ? (error.stack ?? error.message) : String(error),
	)
	process.exit(1)
})
